            { "id", ((object)requestId).ToString() },
            { "subMessageHashes", subMessageHashes },
            { "messageHashes", messageHashes },
            { "symbols", symbols },
            { "topic", "trades" },
        };
        return await this.watchMultiple(url, messageHashes, this.extend(request, query), messageHashes, subscription);
    }

