    public virtual void handleUserDataStreamSubscribe(WebSocketClient client, object message)
    {
        //
        //   {
        //     "id": 1,
        //     "status": 200,
        //     "result": {
        //         "subscriptionId": 0
        //     }
        //   }
        //
        string? messageHash = this.safeString(message, "id");
